import{_ as a,o as t,c as i,a3 as o}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"生成与应用","description":"讲解检索证据如何进入模型上下文、形成引用回答，并在多轮对话中保持查询独立。","frontmatter":{"title":"生成与应用","description":"讲解检索证据如何进入模型上下文、形成引用回答，并在多轮对话中保持查询独立。"},"headers":[],"relativePath":"py-agent/knowledge/generation-application/index.md","filePath":"py-agent/knowledge/generation-application/index.md","lastUpdated":1785318762000}'),n={name:"py-agent/knowledge/generation-application/index.md"};function l(r,e,d,p,c,s){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="生成与应用" tabindex="-1">生成与应用 <a class="header-anchor" href="#生成与应用" aria-label="Permalink to &quot;生成与应用&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>检索到文档不等于完成 RAG。本分组处理检索之后的应用链路：证据选择、上下文格式、拒答、引用映射，以及多轮对话中的指代消解和查询重写。</p><h2 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h2><p>完成后，你应该能够：</p><ol><li>把候选文档转换为带稳定证据 ID 的模型上下文；</li><li>在 Token 预算内选择、去重和组织证据；</li><li>生成可以映射回原始来源的引用回答；</li><li>区分“没有证据”“证据冲突”和“模型没有遵守格式”；</li><li>将对话问题改写为独立检索查询，同时避免历史污染。</li></ol><h2 id="_2-文章顺序" tabindex="-1">2. 文章顺序 <a class="header-anchor" href="#_2-文章顺序" aria-label="Permalink to &quot;2. 文章顺序&quot;">​</a></h2><ol><li><a href="/py-agent/knowledge/generation-application/context-construction-cited-answers">上下文构建与引用回答</a>：证据到回答的完整契约。</li><li><a href="/py-agent/knowledge/generation-application/conversational-rag">对话式 RAG</a>：历史、独立查询和会话状态。</li></ol><h2 id="_3-分组边界" tabindex="-1">3. 分组边界 <a class="header-anchor" href="#_3-分组边界" aria-label="Permalink to &quot;3. 分组边界&quot;">​</a></h2><p>本组假设上游已经返回候选证据，不重复讲向量索引与排序算法。回答质量的系统评测放在“RAG 质量工程”。</p>',10)])])}const g=a(n,[["render",l]]);export{h as __pageData,g as default};
